#!/usr/bin/env python3
"""Verify real human SlideAudit original images, produce compact SWAAG research.

Requires completed frozen 343 source-image pixel/OpenCV/Tesseract predictions,
actual local CLIP ViT-B32 scores and human-labelled category scoring; optional
source-transfer fixed logistic model must also complete before publication.
Never include original photo, OCR strings, human raw bounding boxes, model
weight bytes, personal data or third-party source file paths in Git.
"""
from pathlib import Path
import json,hashlib,datetime,collections,statistics
from scipy.stats import beta
VAR=Path('/data/var/perceptual-independent-20261024')
REPO=Path(__file__).resolve().parents[2]
OUT=REPO/'docs/research/perceptual-slideaudit-human-visual-evidence-2026-10-25.json'
DOC=REPO/'docs/research/perceptual-independent-real-human-layout-2026-10-25.md'
TASKS=['Content Overflow/Cut-off','Occluded Content','Insufficient Color Contrast for Readability']

def source(name):
 path=VAR/name;data=path.read_bytes();return json.loads(data),hashlib.sha256(data).hexdigest()

def pct(x):return 'n/a' if x is None else f'{x*100:.1f}%'
def exact_binom_ci(k,n):
 if not n:return None
 low=0.0 if k==0 else float(beta.ppf(.025,k,n-k+1))
 high=1.0 if k==n else float(beta.ppf(.975,k+1,n-k))
 return [round(low,4),round(high,4)]

def main():
 if OUT.is_file() or DOC.is_file():
  print('PRIOR_PUBLISHED_EVIDENCE_PRESERVED',str(OUT),str(DOC));return
 chosen,hchosen=source('slideaudit_selection_20261025.json')
 img,himg=source('slideaudit_343_image_only_ocr_cv_frozen_20261025.json')
 cv,hcv=source('slideaudit_human_visual_label_performance_20261025.json')
 clip,hclip=source('slideaudit_343_clip_image_only_20261025.json')
 cliptest,hcliptest=source('slideaudit_clip_343_human_flaw_comparison_20261025.json')
 learned,hlearned=source('slideaudit_343_human_label_source_transfer_20261025.json')
 assert chosen['n_selected_unique']==343 and img['status']==clip['status']=='complete'
 assert len(img['input_predictions'])==len(clip['predictions'])==343
 assert all(r['status']=='complete' for r in clip['predictions'].values())
 assert chosen['source_input_2400_annotations_sha256']=='b7903596d3d10eddd9efd3581a56a568bf7f948ae833a74b1941a5a70d377c1b'
 assert img['source_selection_sha256']==hchosen
 assert cliptest['model_frozen_predictions_sha256']==hclip
 assert cv['frozen_prediction_sha256']==himg
 assert learned['raw_343_pixels_model_predictions_sha256']==himg
 counts={'Content Overflow/Cut-off':82,'Occluded Content':105,'Insufficient Color Contrast for Readability':20}
 summary={}
 table=[]
 for t in TASKS:
  sc=chosen['task_counts'][t];assert sc['strong_positive_count']==sc['matched_negative_count']==counts[t]
  D=cv['tasks'][t];C=cliptest['tasks'][t];L=learned['task_results'][t]
  baseline=D['confusion_on_balanced_human_source'];clipcm=C['binary_prompt_rule'];model=L['out_of_source_combined_model']
  assert baseline['n']==clipcm['n']==model['n']==2*counts[t]
  assert baseline['TP']+baseline['FN']==counts[t]
  assert baseline['FP']+baseline['TN']==counts[t]
  assert clipcm['TP']+clipcm['FN']==counts[t]
  assert model['TP']+model['FN']==counts[t]
  primary=D['selected_primary_predeclared_continuous_feature']; proxy_auc=D['continuous_scores_no_threshold_fitting'][primary]['AUROC']
  summary[t]={'human_strong_positive_count':counts[t],'matched_strong_negative_count':counts[t],'source_weak_positive_excluded':sc['original_weak_positive_not_adjudicated'],'source_strata_matched_without_fallback':sc['source_strata_matched_without_fallback'],'fixed_OCR_OpenCV':baseline,'image_only_continuous_indicator_AUROC':proxy_auc,'CV_ocr_operational_coverage':D['operational_OCR_coverage'],'CV_complete_case_confusion':D['confusion_when_both_OCR_completed'],'CV_marginal_95pct_exact_binomial_recall_CI':exact_binom_ci(baseline['TP'],counts[t]),'CV_marginal_95pct_exact_binomial_false_alarm_rate_CI':exact_binom_ci(baseline['FP'],counts[t]),'image_only_vision_CLIP_ViTB32':clipcm,'CLIP_vision_ranking_AUROC':C['AUROC_positive_defect_prompt'],'leave_one_slide_source_out_trained_logistic_pixel_features':model,'source_disjoint_fold_details':{name:{'n':v['heldout_n'],'positives':v['positives'],'negatives':v['negatives'],'model_roc_auc':v['model_withheld_source_confusion']['roc_auc'],'model_TP':v['model_withheld_source_confusion']['TP'],'model_FP':v['model_withheld_source_confusion']['FP'],'model_FN':v['model_withheld_source_confusion']['FN'],'model_TN':v['model_withheld_source_confusion']['TN']} for name,v in L['source_folds'].items()},'bootstrapped95_fixed_OCR_proxy':D['matched_pair_bootstrap_95pct'],'bootstrapped95_CLIP':C['paired_bootstrap_95pct'],'source_human_bbox_localization':D['positive_human_box_coverage']}
  table.append(f"| {t} | {counts[t]} / {counts[t]} | {baseline['TP']}/{counts[t]} | {baseline['FP']}/{counts[t]} | {pct(proxy_auc)} | {clipcm['TP']}/{counts[t]} | {clipcm['FP']}/{counts[t]} | {pct(C['AUROC_positive_defect_prompt'])} | {model['TP']}/{counts[t]} | {model['FP']}/{counts[t]} | {pct(model['roc_auc'])} |")
 rawstatuses=collections.Counter(r['status'] for r in img['input_predictions'].values())
 report={'date':'2026-10-25','objective':'independently validate screenshot-only UI-ish visual defect detectors vs real human labels, rather than metadata-only fixtures','overall_status':'PARTIAL — no generic or source-transfer tested visual model qualifies for autonomous GUI cut-off/overlap/contrast acceptance','source':'SlideAudit UIST 2025 real/synthetically altered human-rated presentation slides, CC BY4, 2400 source annotations; 343 source-type/alteration-matched unique original images evaluated','dataset_github_revision':'642d490b7c1d2e78a50a631bfd359433397f3ecf','source_data_all_outside_project_git':True,'source_sha256':{'selection_2400_human_reviewed':hchosen,'image_only_cv_ocr_343':himg,'cv_human_score':hcv,'CLIP_real_image_model_predictions':hclip,'CLIP_human_score':hcliptest,'source_disjoint_learned_cv_human_scores':hlearned},'dataset':{'all_labelled_slide_images':2400,'source_original_unique_image_cases_tested':343,'human_reviewers_per_image':3,'matched_human_positive_to_category_specific_negative_controls':True,'origin_types':['Gemini','gdcdataset','Google'],'alteration_types':['nojitter','texture','layout','alignment'],'human_has_strong_agreement_required':True,'no_original_slide_scripts_executed':True,'unverified_or_disagreed_annotations_excluded_per_category':True,'original_GUI_not_proven':'These are authored slide designs, some intentionally modified, NOT actual desktop/web/mobile GUI screenshots.'},'image_models':{'OpenAI_CLIP':'ViT-B32 578MB local pretrained frozen checkpoint, 224x224 input, six fixed zero-shot prompts, no trained threshold; CPU one thread','deterministic':'Tesseract 5.3.4 PSM11 + OpenCV 4.x image features, fixed border 2%, text word IoU 0.15 and pixel-contrast proxy <4.5 in >=35% boxes, NOT WCAG contrast','transfer_learned':'SimpleImputer,StandardScaler,class-weighted logistic regression on fixed 16 image-derived features, trained on two original slide source families, evaluated on completely different source family, no hyperparameter tuning'},'resource':{'OCR_OpenCV_pixel_only_wall_s':img['current_iteration_wall_s'],'OCR_OpenCV_peak_RSS_KB':img['peak_rss_kb'],'OCR_OpenCV_statuses':dict(rawstatuses),'CLIP_local_CPU_wall_s':clip['total_cpu_wall_seconds'],'CLIP_max_RSS_KB':clip['peak_rss_kb'],'GPU_inference_used':False},'tasks':summary,'limitations':['Balanced target-category positives/negative controls selected by author human labels, therefore a per-study enriched test and no deployment prevalence; reported precision does not transfer to real GUIs','Human source has_strong_agreement is the released dataset flag, not a guaranteed unanimous three-annotator adjudication; only 20 strong low-contrast positives','Some source images are deliberately altered slide images, real authored origins mixed; category-negative slides may exhibit other mistakes','Low color-contrast inferred by grayscale pixel quantiles inside OCR word boxes is NOT proper foreground/background WCAG computed contrast and can mislabel photos/gradients','Clipping inside widget containers is not equivalent to text touching physical slide boundary; occluded shapes may not appear as two OCR word boxes','Generic CLIP prompt softmax is uncalibrated; no semantic visual judgment, cannot locate faults or certify layout','Source-trained 16-feature classifier used category human labels for fitting and tested leave-one-slide-source-type-out; not a pretrained image model or independent untouched deployment set','Operational OCR timeouts are ABSTAINS, not genuine negative judgments. Report complete paired coverage alongside conservative default-negative counts','Bounding box localization against human broad regions requires random chance-area comparison; high center hit can be trivial if gold region covers much of slide','No guarantee of actual application GUI performance; narrow companion to real Firefox ScreenParser and W3C axe-core benchmarks already committed']}
 OUT.write_text(json.dumps(report,indent=2)+'\n')
 content=f'''# Image-only visual defect analyzers versus human-reviewed real slide renderings\n\n**25 October 2026 — SWAAG perceptual research. Status: PARTIAL.** This is a supplementary benchmark for GUI-like visual quality properties: content cut-off, occluded/overlapped content, and insufficient text contrast. The images are actual authored presentation-slide renderings, not application screenshots. Several versions were deliberately modified; this is not a direct validation of a GUI deployment. The larger original owner-testing question remains unanswered for complete GUI semantics, physical industrial 3D, and naturally occurring temporal video artifacts.\n\n## Original human evidence and falsifiable test contract\n\nThe independent [SlideAudit UIST 2025 source](https://github.com/zhuohaouw/SlideAudit/tree/642d490b7c1d2e78a50a631bfd359433397f3ecf) contains **2,400 original slide raster images**, 19 manually reviewed design-deficiency categories and accompanying source descriptions. The study assigned **three annotators per slide**. The experimental selection required the released `has_strong_agreement` flag, retaining **all 82 positive Overflow/Cut-off, 105 positive Occluded Content, and 20 positive Insufficient Color Contrast** cases and exactly as many human category-negative controls matched on the original slide source type and alteration method. The union is **343 distinct original raster slides**. Matching never consulted the output of a proposed detector. Category negatives may have other flaws, and the 20 low-contrast cases are far too few for precise cross-domain estimates. Raw original images and labels remain exclusively under `/data/var/perceptual-independent-20261024`, never tracked in SWAAG Git.\n\nThe same raster inputs were supplied to two distinctly different predictors **before reading the human labels**. First, a fixed deterministic OpenCV and Tesseract PSM11 (5.3.4) pipeline measured visual text boxes, outer-canvas border occupancy, OCR-box overlap and inside-word grayscale contrast. Its binary rules were **word at 2% canvas border** for cut-off, **two word boxes overlapping IoU >=0.15** for occlusion, and **at least 35% of word-box grayscale contrast ratios under 4.5** for low text contrast. The last rule is explicitly *not* valid CSS/WCAG foreground-background contrast. Second, a real frozen **OpenAI CLIP ViT-B/32** image encoder processed every original image with six fixed positive/negative zero-shot prompts; output was the relative prompt probability at an untrained 0.5 decision threshold. The vision model was run locally on Nitro CPU with GPU explicitly disabled. Both raw outputs and input SHA-256 receipts were frozen before human label scoring. A third, clearly distinguished exploratory **source-trained logistic regression** consumed the 16 predefined pixel/OCR features, training on two slide-source families and evaluating the third, rotating across all three. This model is neither a universal visual model nor an untouched final deployment evaluation.\n\n## Direct actual-image results\n\nEach task's 'FP' column means **a flag on a strong-agreement slide annotated *not* to contain that specific defect**; it does not mean the slide is otherwise certified perfect. The cases were deliberately balanced so reported precision is not deployment precision. The AUROC uses a predeclared continuous score; no threshold was optimized on the human evaluation labels.\n\n| Source visual property | Human yes/no pairs | OpenCV/OCR true positives | OpenCV/OCR false alerts | Fixed CV ranking AUROC | CLIP true positives | CLIP false alerts | CLIP AUROC | Source-heldout fitted model TP | Fitted model false alerts | Fitted model AUROC |\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n'''+"\n".join(table)+"\n\n"
 content+='''**Sample-size warning:** only 20 human-strong low-contrast positives and 20 matched negative slides exist in this selected subset. If none of 20 controls is flagged, the two-sided 95% exact binomial interval on the underlying false-alarm probability still extends to about **16.8%** under an independent-case assumption; the bootstrap's degenerate [0,0] FPR interval cannot by itself establish near-perfect specificity. Matched slide families add potential correlation. The compact results store both matched-pair bootstrap intervals and exact marginal confidence bounds.

The accompanying `perceptual-slideaudit-human-visual-evidence-2026-10-25.json` retains all exact confusion matrices, source-stratified comparisons, 3,000 matched-pair bootstrap intervals for the fixed rules/CLIP, origin-heldout source transfer outcomes, OCR abstentions, and whether top candidate boxes landed inside the original human flaw region beyond broad-box chance coverage. **No single threshold is calibrated into an acceptance gate** merely because one column appears favorable.\n\n## Interpretation and deployment decision\n\nImage-only OCR boxes are useful where a separate source document tells the agent which text is required and what may truncate; their absence or presence does not by itself prove the meaning of the rendered UI. Physical slide-border proximity is not DOM widget-content clipping, and OCR text-box overlap cannot inspect hidden sprites/graphics or intention. Pixel luminance inside a text word's rectangle mixes glyphs, anti-aliasing and backgrounds; a genuine WCAG test requires exact foreground and composed background (or a validated image-based estimator). CLIP ViT-B/32 is a **generic pretrained vision-image similarity model**, not an industrial or GUI-error classifier, and its zero-shot prompt preference cannot be treated as a calibrated defect probability. A fitted classifier can memorize the specific original slide-augmentation statistics even when heldout by source. These are genuine image-based comparisons against human labels, not synthetic metadata toy success claims, but the medium/task and label uncertainty still limit transfer.\n\nEarlier local evaluations remain binding negative evidence: Thor Qwen3-VL clipped-text failure (3/4), 311 human-tagged Scry UI pairs with high SSIM no-tagged flags, real ScreenParser v2 whole-page source-target IoU 11/32 at 0.5 (not a defect model), Tesseract exact source entity-label recovery 820/1733 on 154 original diagrams, five-VLM expert 3D missing-parts unreliability, and human motion-error timing often indistinguishable from a random-peak control. The safe complementary strategy is **browser DOM client/scroll/ancestor geometry plus axe-core for properties those tools truly measure**, text OCR and visual parsing only as evidence, source-based graph/CAD/physics constraints for machinery and diagrams, and timeline/frame-timestamp verification with separate perceptual interpretation for video.\n\n## Candidate availability, provenance and resource restrictions\n\nRelevant newer [UI-Lens CVPR 2026](https://huggingface.co/datasets/wuhuohua/UI_lens) evaluates real commercial mobile UI overflow and overlap, and the authors report severe performance limitations (roughly 20% and 31% task-average F1 respectively); its dataset is gated by a terms/contact step and was **not silently accessed or tested**. [OwlEye ASE 2020](https://github.com/franklinbill/OwlEye) reports human-tested UI defect detection accuracy, but its pinned public repository contains only a handful of files and missing full test image/model artifacts; these author metrics are **not a verified local reproduction**. The independently published [GUIPilot dataset](https://zenodo.org/records/15107436) is additionally relevant for mobile GUI consistency, but its archive contains apparent sensitive account information embedded in filenames; **no screenshots or credential-bearing paths were extracted, processed or committed**. It is a GUI consistency dataset, not a clean human-labeled cut-off/overlap/contrast test without further privacy review.\n\nSource and model checkpoints and all raw prediction strings remain under `/data/var`; the SWAAG project contains only code and source-hash linked compact research. Tests ran CPU-only with low process priority and no active 3D render, voice or shared GPU service interruption. Original recordings and prior negative outcomes were preserved. Until heldout human ratings show suitably low false-alarm and miss rates on the owner's actual final GUI, CAD and video outputs, **this research remains PARTIAL rather than a working complete visual acceptance toolkit**.\n'''
 DOC.write_text(content)
 print('SLIDEAUDIT_HUMAN_SOURCE_LINKED_REPORT_SAVED',DOC,'MD_BYTES',DOC.stat().st_size,'AGG_BYTES',OUT.stat().st_size,'RAW_STATUS',dict(rawstatuses),'CPU_SECONDS',img['current_iteration_wall_s'],clip['total_cpu_wall_seconds'])
if __name__=='__main__':main()
